  "pay.3ds.smsFrom": ["AlsatPort Bank", "AlsatPort Bank", "AlsatPort Bank", "AlsatPort Bank", "AlsatPort Bank"],
  "pay.3ds.smsBody": ["3D Secure kodunuz: {code} Bu kodu banka ekranına girin. Kart verisi AlsatPort’ta saklanmaz.", "Your 3D Secure code: {code} Enter it on the bank screen. Card data is not stored at AlsatPort.", "Ihr 3D-Secure-Code: {code} Kartendaten werden nicht gespeichert.", "رمز 3D Secure: {code} لا تُحفظ بيانات البطاقة.", "Код 3D Secure: {code} Данные карты не хранятся."],
  "pay.3ds.missing": ["Doğrulama oturumu bulunamadı.", "Verification session not found.", "Keine Prüfsitzung.", "جلسة التحقق غير موجودة.", "Сессия проверки не найдена."],
  "pay.3ds.expired": ["SMS kodunun süresi doldu. Ödemeyi yeniden başlatın.", "The SMS code expired. Start payment again.", "SMS-Code abgelaufen. Zahlung neu starten.", "انتهت صلاحية رمز SMS. أعد الدفع.", "Срок SMS-кода истёк. Начните оплату снова."],
  "pay.3ds.locked": ["Çok fazla hatalı deneme. Yeni kod için ödemeyi yeniden başlatın.", "Too many invalid attempts. Restart payment for a new code.", "Zu viele Fehlversuche. Zahlung neu starten.", "محاولات خاطئة كثيرة. أعد الدفع.", "Слишком много ошибок. Начните оплату снова."],
